const nonEnglish = Object.keys(locales).filter((locale) => locale !== 'en');
export const translations = Object.fromEntries(Object.keys(locales).map((locale) => [locale, Object.create(null)]));

for (const row of [lines, navigation, workflow, additional].join('\n').trim().split('\n')) {
  if (!row) continue;
  const [key, ...values] = row.split('|');
  for (const [index, locale] of nonEnglish.entries()) {
    if (values[index]) translations[locale][key] = values[index];
  }
}

Object.assign(translations['zh-CN'], zh, guideChinese);
for (const locale of nonEnglish) {
  for (const [alias, key] of Object.entries(aliases)) {
    if (alias in translations[locale]) continue;
    if (translations[locale][key]) translations[locale][alias] = translations[locale][key];
  }
}

export function translate(locale, key, variables = {}) {
  const text = translations[locale]?.[key] ?? key;
  return text.replace(/\{(\w+)\}/g, (token, name) => String(variables[name] ?? token));
}
